import pytest
from app import take_first
@pytest.mark.parametrize("items", [[],[7],["a","b","c"],list(range(8))])
@pytest.mark.parametrize("n", range(0,12))
def test_prefix(items,n):
    before = list(items)
    assert take_first(items,n) == items[:n]
    assert items == before
def test_invalid_prefix():
    with pytest.raises(ValueError): take_first([], -2)

reference_sources.app.py:
def take_first(items, n):
    if n < 0:
        raise ValueError("negative count")
    return items[:n]

