import pytest
from app import sum_inclusive
@pytest.mark.parametrize("n", range(0,101))
def test_closed_form(n): assert sum_inclusive(n) == n*(n+1)//2
def test_invalid_sum():
    with pytest.raises(ValueError): sum_inclusive(-9)

reference_sources.app.py:
def sum_inclusive(n):
    if n < 0:
        raise ValueError("negative limit")
    return n*(n+1)//2
